// Everything the review ask needs is worked out once, here, so the rest of the workflow only reads it.
const s = $('Your settings').first().json;
const b = $('Job done').first().json.body || {};
const tz = s.timezone || 'America/New_York';
const now = DateTime.now().setZone(tz);

const digits = String(b.phone || '').replace(/\D/g, '');
const phone = digits.length === 10 ? '+1' + digits : (digits.length === 11 && digits[0] === '1' ? '+' + digits : '');
const pretty = phone ? phone.replace(/^\+1(\d{3})(\d{3})(\d{4})$/, '($1) $2-$3') : '';
const name = String(b.name || '').trim();
const first = name.split(/\s+/)[0] || 'there';
const job = String(b.job || '').trim() || 'the job';
const biz = String(s.business_name || '').trim() || 'us';
const link = String(s.review_link || '').trim();

// Read numbers explicitly. A plain "value || default" would throw away a configured 0,
// which is exactly what you set while testing.
const num = (v, dflt) => {
  if (v === null || v === undefined || String(v).trim() === '') return dflt;
  const n = Number(v);
  return Number.isFinite(n) && n >= 0 ? n : dflt;
};
const delay = num(s.delay_minutes, 120);
const repeatDays = num(s.repeat_days, 90);

const problems = [];
if (!phone) problems.push('phone "' + (b.phone || '') + '" is not a usable US mobile number');
if (!/^https?:\/\/\S+$/.test(link) || /YOUR-REVIEW-LINK/i.test(link)) problems.push('the review link in Your settings is not set');
if (!s.business_number || !s.owner_cell) problems.push('your Twilio number or your cell is missing from Your settings');

// Quiet hours. The window can wrap past midnight (20:00 to 08:00) or not (13:00 to 14:00).
const hm = (v, d) => { const p = String(v || d).split(':').map(Number); return [p[0] || 0, p[1] || 0]; };
const [qsH, qsM] = hm(s.quiet_start, '20:00');
const [qeH, qeM] = hm(s.quiet_end, '08:00');
const qs = qsH * 60 + qsM, qe = qeH * 60 + qeM;
const mins = d => d.hour * 60 + d.minute;
const inQuiet = d => qs === qe ? false : (qs > qe ? (mins(d) >= qs || mins(d) < qe) : (mins(d) >= qs && mins(d) < qe));
// A review ask is never urgent, so one that would land in quiet hours waits until they end.
const later = d => {
  if (!inQuiet(d)) return d;
  let t = d.set({ hour: qeH, minute: qeM, second: 0, millisecond: 0 });
  if (t < d) t = t.plus({ days: 1 });
  return t;
};
const sendAt = later(now.plus({ minutes: delay }));

// Two "job done" posts for the same customer close together (a double click, a retry) would both
// be waiting when the first text goes out, so neither would see the other in Twilio's log.
// Waiting asks are remembered here until two minutes after their send time. From then on the text
// is in Twilio's log, which is what the check before sending reads. This memory only works while
// the workflow is active; test runs from the editor do not keep it.
const memory = $getWorkflowStaticData('global');
memory.waiting = memory.waiting || {};
for (const [k, v] of Object.entries(memory.waiting)) {
  if (DateTime.fromISO(v) < now.minus({ minutes: 2 })) delete memory.waiting[k];
}
const alreadyWaiting = !!(phone && memory.waiting[phone]);
if (problems.length === 0 && !alreadyWaiting) memory.waiting[phone] = sendAt.toUTC().toISO();

const fill = t => String(t || '')
  .replace(/\{name\}/g, first).replace(/\{business\}/g, biz)
  .replace(/\{job\}/g, job).replace(/\{link\}/g, link)
  .replace(/[ \t]+/g, ' ').trim();

const ok = problems.length === 0 && !alreadyWaiting;
const who = (name || 'A customer') + (pretty ? ' ' + pretty : '');
return [{ json: {
  ok,
  reason: problems.length ? problems.join('; ') : (alreadyWaiting ? 'a review ask for this number is already waiting to go out' : ''),
  tell_owner_now: problems.length > 0,
  phone, pretty, name: first, job, review_link: link,
  business_number: s.business_number, owner_cell: s.owner_cell,
  send_at: sendAt.toUTC().toISO(),
  send_at_local: sendAt.toFormat("ccc LLL d 'at' h:mm a"),
  // Twilio filters by calendar day, so ask for everything from the day before the window starts.
  since_day: now.toUTC().minus({ days: repeatDays + 1 }).toFormat('yyyy-MM-dd'),
  repeat_days: repeatDays,
  message: fill(s.review_text),
  owner_problem: 'Review ask NOT started for ' + who + ': ' + problems.join('; ') + '.',
  owner_sent: 'Review ask sent to ' + who + ' for ' + job + '.',
  owner_skipped: 'Review ask skipped for ' + who + ': they were already asked in the last ' + repeatDays + ' days.',
  owner_failed: 'Review ask to ' + who + ' did not send. Twilio said: '
} }];

// Looks at every text your number sent this customer inside the repeat window.
// If any of them carried your review link and was not a failed send, they have been asked already.
// Twilio logs failed attempts too, so those are left out: a customer who never got the text can be asked.
const p = $('Prepare the ask').first().json;
const since = DateTime.fromISO(p.send_at).minus({ days: p.repeat_days });
const notSent = ['failed', 'undelivered', 'canceled'];
const msgs = ($json.messages || []).filter(m => m.direction && m.direction.startsWith('outbound') && !notSent.includes(m.status));
const asked = msgs.filter(m => String(m.body || '').includes(p.review_link) && DateTime.fromRFC2822(m.date_created) >= since);

return [{ json: {
  asked_before: asked.length > 0,
  last_asked: asked.length ? DateTime.fromRFC2822(asked[0].date_created).toISODate() : '',
  checked: msgs.length
} }];
